struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    int ops = 0;
    int dfs(TreeNode* node) {
        if (!node) return 0;
        if (!node->left && !node->right) return node->val;

        int l_val = dfs(node->left);
        int r_val = dfs(node->right);
        int child_sum = l_val + r_val;

        ops += std::abs(node->val - child_sum);
        return child_sum;
    }
public:
    int minOperationsToStabilize(TreeNode* root) {
        ops = 0;
        dfs(root);
        return ops;
    }
};

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class Solution {
    private int ops = 0;

    private int dfs(TreeNode node) {
        if (node == null) return 0;
        if (node.left == null && node.right == null) return node.val;

        int lVal = dfs(node.left);
        int rVal = dfs(node.right);
        int childSum = lVal + rVal;

        ops += Math.abs(node.val - childSum);
        return childSum;
    }

    public int minOperationsToStabilize(TreeNode root) {
        ops = 0;
        dfs(root);
        return ops;
    }
}

